# SPDX-License-Identifier: GPL-3.0-or-later
# darktable uses libarchive for .dtdata sidecars and zip extraction.
NAME=libarchive
VERSION=3.8.11
LICENSE=BSD-2-Clause
URL=https://github.com/libarchive/libarchive/releases/download/v$VERSION/libarchive-$VERSION.tar.gz
SHA256=900fe9fc7237c2b04f090f3c3648de8fe597525771f5035016537ce2d667d12b
DEPENDS="ndk-zlib"
build() {
  dta_cmake -DENABLE_OPENSSL=OFF -DENABLE_MBEDTLS=OFF -DENABLE_NETTLE=OFF -DENABLE_LIBB2=OFF \
    -DENABLE_LZ4=OFF -DENABLE_LZO=OFF -DENABLE_LZMA=OFF -DENABLE_ZSTD=OFF -DENABLE_ZLIB=ON \
    -DENABLE_BZip2=OFF -DENABLE_LIBXML2=OFF -DENABLE_EXPAT=OFF -DENABLE_PCREPOSIX=OFF \
    -DENABLE_PCRE2POSIX=OFF -DENABLE_LIBGCC=OFF -DENABLE_CNG=OFF -DENABLE_TAR=OFF \
    -DENABLE_CPIO=OFF -DENABLE_CAT=OFF -DENABLE_UNZIP=OFF -DENABLE_XATTR=OFF -DENABLE_ACL=OFF \
    -DENABLE_ICONV=ON -DENABLE_TEST=OFF -DENABLE_INSTALL=ON
}
